package ly.com.tahaben.notification_filter_domain.model

data class PriorityDeliverySetting(
    val cadence: DeliveryCadence,
    val budgetBehavior: BudgetBehavior,
) {
    companion object {
        val DEFAULTS: Map<NotificationPriority, PriorityDeliverySetting> = mapOf(
            NotificationPriority.CRITICAL to PriorityDeliverySetting(
                DeliveryCadence.IMMEDIATELY,
                BudgetBehavior.IGNORING,
            ),
            NotificationPriority.HIGH to PriorityDeliverySetting(
                DeliveryCadence.EVERY_HOUR,
                BudgetBehavior.RESPECTING,
            ),
            NotificationPriority.MEDIUM to PriorityDeliverySetting(
                DeliveryCadence.EVERY_OTHER_HOUR,
                BudgetBehavior.RESPECTING,
            ),
            NotificationPriority.LOW to PriorityDeliverySetting(
                DeliveryCadence.ONCE_DAILY,
                BudgetBehavior.RESPECTING,
            ),
        )

        fun defaultFor(priority: NotificationPriority): PriorityDeliverySetting =
            DEFAULTS[priority] ?: PriorityDeliverySetting(
                DeliveryCadence.EVERY_HOUR,
                BudgetBehavior.RESPECTING,
            )
    }
}
package ly.com.tahaben.notification_filter_domain.model

enum class NotificationPriority(val level: Int) {
    CRITICAL(1),
    HIGH(2),
    MEDIUM(3),
    LOW(4);

    val pointCost: Int
        get() = when (this) {
            CRITICAL -> 0
            HIGH -> 2
            MEDIUM -> 4
            LOW -> 8
        }

    fun degraded(levels: Int = 1): NotificationPriority = fromLevel((level + levels).coerceAtMost(4))
    fun improved(levels: Int = 1): NotificationPriority = fromLevel((level - levels).coerceAtLeast(1))

    companion object {
        fun fromLevel(level: Int): NotificationPriority =
            entries.firstOrNull { it.level == level } ?: MEDIUM
    }
}
package ly.com.tahaben.notification_filter_domain.delivery

data class DeliveryTimeContext(
    val boundaryIndex: Int,
    val boundariesPerDay: Int,
    val boundaryIntervalMinutes: Int,
    val minuteOfDay: Int,
    val calendarHour: Int,
    val dayOfYear: Int,
    val testingMode: Boolean = false,
    val localDay: String = "",
) {
    /** Minute-of-day used for schedule/budget lookups (3 min = 1 h in testing mode). */
    val scheduleMinuteOfDay: Int
        get() = if (testingMode) boundaryIndex * PRODUCTION_BOUNDARY_MINUTES else minuteOfDay

    /** Key for hourly passthrough rate limiting (one virtual hour per boundary in testing). */
    val passthroughWindowKey: Int
        get() = if (testingMode) boundaryIndex else calendarHour

    companion object {
        const val TESTING_BOUNDARY_MINUTES = 3
        const val PRODUCTION_BOUNDARY_MINUTES = 60

        fun from(
            calendarHour: Int,
            minuteOfDay: Int,
            dayOfYear: Int,
            testingMode: Boolean,
            localDay: String = "",
        ): DeliveryTimeContext {
            return if (testingMode) {
                DeliveryTimeContext(
                    boundaryIndex = minuteOfDay / TESTING_BOUNDARY_MINUTES,
                    boundariesPerDay = 24 * 60 / TESTING_BOUNDARY_MINUTES,
                    boundaryIntervalMinutes = TESTING_BOUNDARY_MINUTES,
                    minuteOfDay = minuteOfDay,
                    calendarHour = calendarHour,
                    dayOfYear = dayOfYear,
                    testingMode = true,
                    localDay = localDay,
                )
            } else {
                DeliveryTimeContext(
                    boundaryIndex = calendarHour,
                    boundariesPerDay = 24,
                    boundaryIntervalMinutes = PRODUCTION_BOUNDARY_MINUTES,
                    minuteOfDay = minuteOfDay,
                    calendarHour = calendarHour,
                    dayOfYear = dayOfYear,
                    testingMode = false,
                    localDay = localDay,
                )
            }
        }

        fun msToNextBoundary(
            minute: Int,
            second: Int,
            millis: Int,
            testingMode: Boolean,
            localDay: String = "",
        ): Long {
            return if (testingMode) {
                val minuteInSlot = minute % TESTING_BOUNDARY_MINUTES
                val secondsRemaining = (TESTING_BOUNDARY_MINUTES - minuteInSlot) * 60 - second
                (secondsRemaining * 1000L - millis).coerceAtLeast(5_000L)
            } else {
                val minutesRemaining = 60 - minute
                ((minutesRemaining * 60 - second) * 1000L - millis).coerceAtLeast(60_000L)
            }
        }
    }
}
package ly.com.tahaben.notification_filter_domain.delivery

import java.time.Clock

/** Production wall-clock adapter; always carries a calendar date including the year. */
object DeliveryClock {
    /** Resolve the phone zone at use time, including changes while the process remains alive. */
    val systemClock: Clock = object : Clock() {
        override fun getZone(): java.time.ZoneId = java.time.ZoneId.systemDefault()
        override fun withZone(zone: java.time.ZoneId): Clock = Clock.system(zone)
        override fun instant(): java.time.Instant = java.time.Instant.now()
    }
    fun current(testingMode: Boolean, clock: Clock = systemClock): DeliveryTimeContext {
        val now = clock.instant().atZone(clock.zone)
        return DeliveryTimeContext.from(now.hour, now.hour * 60 + now.minute, now.dayOfYear, testingMode, now.toLocalDate().toString())
    }
}

